#if BEAMIO_TEST_HOOKS
import XCTest
@testable import ConetChatSDK

/// The first identity with the real OpenPGP wrapper and the real signing (iOS builds with the X-19 framework): the key is generated by X-19, the registration is signed by the account key,
/// the mock "server" writes what it receives onto both mock endpoints, and the coordinator finds it, then saves the record with the route. Synthetic data only; no network.
final class NewAccountX19Tests: XCTestCase {
	private let account = PgpMigrationTestSupport.eoa
	private let routeArmor = "-----BEGIN PGP PUBLIC KEY BLOCK-----\nsynthetic-route\n-----END PGP PUBLIC KEY BLOCK-----"

	private final class Store: BeamioChatWalletKeyStoring {
		var keys: [String: Data] = [:]
		func write(eoa: String, key: Data) -> Bool { keys[eoa.lowercased()] = key; return true }
		func read(eoa: String) -> Data? { keys[eoa.lowercased()] }
		func enumerateKeyOwners() -> [String]? { Array(keys.keys) }
		func delete(eoa: String) { keys[eoa.lowercased()] = nil }
		func enumerateMnemonicCreations() -> [BeamioChatKeyCreation]? { enumerateKeyOwners()?.map { BeamioChatKeyCreation(owner: $0, created: nil) } }
		func mnemonicAccountState(owner: String) -> BeamioMnemonicAccountState { (enumerateKeyOwners() ?? []).contains { $0.lowercased() == owner.lowercased() } ? .valid : .absent }
		func migrationMarkerExists(eoa: String) -> Bool { false }
		func setMigrationMarker(eoa: String) -> Bool { true }
	}

	private var savedStore: BeamioChatWalletKeyStoring!
	private var savedTransport: ((URL, Data) -> Result<Data, Error>)!
	private var savedMemory: BeamioChatPgpKeychain.MemoryRecords?
	private var savedSecond: URL?
	private var savedApi: URL?
	// the chain as both mock endpoints hold it
	private var chainArmor = ""
	private var chainBackup = ""
	private var posted: [[String: Any]] = []

	private func word(_ n: Int) -> [UInt8] { [UInt8](repeating: 0, count: 24) + withUnsafeBytes(of: UInt64(n).bigEndian) { Array($0) } }
	private func encodedString(_ s: String) -> [UInt8] {
		let data = Array(s.utf8)
		return word(data.count) + data + [UInt8](repeating: 0, count: (32 - data.count % 32) % 32)
	}
	private func hex(_ bytes: [UInt8]) -> String { "0x" + bytes.map { String(format: "%02x", $0) }.joined() }

	override func setUp() {
		super.setUp()
		savedStore = BeamioNativeWallet.keyStore
		savedTransport = AddressPGPChain.transport
		savedMemory = BeamioChatPgpKeychain.memory
		savedSecond = AddressPGPChain.shellEndpointSecond
		savedApi = BeamioPGPRegistrar.apiBase
		let store = Store()
		var key = PgpMigrationTestSupport.armorA
		if key.hasPrefix("0x") { key.removeFirst(2) }
		store.keys[account] = Data(stride(from: 0, to: key.count, by: 2).map { UInt8(key[key.index(key.startIndex, offsetBy: $0) ..< key.index(key.startIndex, offsetBy: $0 + 2)], radix: 16)! })
		BeamioNativeWallet.keyStore = store
		NativeAccountPointerIsolation.begin()
		BeamioChatPgpKeychain.memory = BeamioChatPgpKeychain.MemoryRecords()
		BeamioConetChatSignBroker.setSignerEoa(account)
		BeamioConetChatModule.setNativeGateForTests(account: account, sessionReady: true)
		AddressPGPChain.configuration = AddressPGPChain.Configuration(contract: "0x" + String(repeating: "1", count: 40), chainId: 224422, rpcURL: URL(string: "https://rpc1.test.invalid")!)
		AddressPGPChain.shellEndpointSecond = URL(string: "https://rpc2.test.invalid")
		BeamioPGPRegistrar.apiBase = URL(string: "https://api.test.invalid")
		AddressPGPChain.transport = { [unowned self] _, body in self.chain(body) }
		chainArmor = ""; chainBackup = ""; posted = []
		BeamioPGPRegistrar.pollDelays = [0, 0]
		BeamioPGPRegistrar.sleep = { _ in }
		BeamioPGPRegistrar.chooseRoute = { [unowned self] in ("node1.test", self.routeArmor) }
		BeamioPGPRegistrar.post = { [unowned self] _, body in
			guard let object = try? JSONSerialization.jsonObject(with: body) as? [String: Any] else { return 400 }
			self.posted.append(object)
			// the server: the base64 public key and the backup are what the contract then returns
			self.chainArmor = object["publicKeyArmored"] as? String ?? ""
			self.chainBackup = object["encrypKeyArmored"] as? String ?? ""
			return 200
		}
		BeamioFirstIdentityCoordinator.isLocked = { _ in false }
		BeamioFirstIdentityCoordinator.legacy = { _ in .absent }
		BeamioPGPIdentityCreate.resetInFlightIdentities()
		BeamioPGPIdentityCreate.resetCompletedIdentities()
	}

	override func tearDown() {
		BeamioNativeWallet.keyStore = savedStore
		AddressPGPChain.transport = savedTransport
		AddressPGPChain.configuration = nil
		AddressPGPChain.shellEndpointSecond = savedSecond
		BeamioPGPRegistrar.apiBase = savedApi
		BeamioChatPgpKeychain.memory = savedMemory
		BeamioPGPRegistrar.post = BeamioPGPRegistrar.defaultPost
		BeamioPGPRegistrar.pollDelays = [2, 4, 8, 16, 32]
		BeamioPGPRegistrar.sleep = { Thread.sleep(forTimeInterval: $0) }
		BeamioPGPRegistrar.chooseRoute = BeamioPGPRegistrar.defaultChooseRoute
		BeamioFirstIdentityCoordinator.isLocked = { BeamioPasscodeSession.shared.isLocked(eoa: $0) }
		BeamioFirstIdentityCoordinator.legacy = { BeamioFirstIdentity.legacy(eoa: $0) }
		BeamioPGPIdentityCreate.resetInFlightIdentities()
		BeamioPGPIdentityCreate.resetCompletedIdentities()
		BeamioConetChatSignBroker.clearSigner()
		BeamioConetChatModule.setNativeGateForTests(account: nil, sessionReady: false)
		NativeAccountPointerIsolation.end()
		super.tearDown()
	}

	private func chain(_ body: Data) -> Result<Data, Error> {
		guard let object = try? JSONSerialization.jsonObject(with: body) as? [String: Any], let method = object["method"] as? String else { return .failure(AddressPGPChain.ReadError.malformed) }
		let result: Any
		switch method {
		case "eth_chainId": result = "0x" + String(224422, radix: 16)
		case "eth_blockNumber": result = "0x20"
		case "eth_getBlockByNumber": result = ["hash": "0x" + String(repeating: "c", count: 64)]
		case "eth_call":
			let call = ((object["params"] as? [Any])?.first as? [String: Any]) ?? [:]
			let data = (call["data"] as? String) ?? ""
			if data.hasPrefix(hex(AddressPGPChain.selector("_pgpKeys(address)"))) {
				let s1 = encodedString(""), s2 = encodedString(chainArmor), s3 = encodedString("")
				result = hex(word(128) + word(128 + s1.count) + word(128 + s1.count + s2.count) + word(chainArmor.isEmpty ? 0 : 1) + s1 + s2 + s3)
			} else {
				result = hex(word(32) + encodedString(chainBackup))
			}
		default: return .failure(AddressPGPChain.ReadError.rpc("unsupported"))
		}
		return .success(try! JSONSerialization.data(withJSONObject: ["jsonrpc": "2.0", "id": 1, "result": result]))
	}

	func testTheFirstIdentityIsGeneratedSignedRegisteredAndSavedWithTheRealWrapper() throws {
		try XCTSkipUnless(BeamioPGPNative.linked, "X-19 framework not linked in this build")
		XCTAssertEqual(BeamioFirstIdentityCoordinator.run(eoa: account), .active)
		XCTAssertEqual(posted.count, 1)
		let body = try XCTUnwrap(posted.first)
		let record = try XCTUnwrap(BeamioChatPgpKeychain.load(eoa: account))
		XCTAssertTrue(record.publicKeyArmor.contains("BEGIN PGP PUBLIC KEY BLOCK"))
		XCTAssertTrue(record.privateKeyArmor.contains("BEGIN PGP PRIVATE KEY BLOCK"))
		XCTAssertEqual(record.routePublicKeyArmor, routeArmor)
		XCTAssertNil(BeamioChatPgpKeychain.loadPending(eoa: account), "the pending key is erased")
		// the request: the public key as the base64 text of its armor, the key ID of the new subkey, the route
		XCTAssertEqual(Data(base64Encoded: body["publicKeyArmored"] as? String ?? "").flatMap { String(data: $0, encoding: .utf8) }, record.publicKeyArmor)
		let identity = try XCTUnwrap(BeamioPGPBackup.keyIdentity(armor: record.publicKeyArmor))
		XCTAssertEqual(body["keyID"] as? String, identity.subkeyKeyID.uppercased())
		XCTAssertEqual(record.pgpKeyId, identity.subkeyKeyID.uppercased())
		XCTAssertEqual(body["routeKeyID"] as? String, "node1.test")
		XCTAssertFalse("\(body)".contains("PRIVATE KEY"))
		// the backup opens with the account key and holds the private armor
		var keyBytes = try XCTUnwrap(BeamioNativeWallet.keyStore.read(eoa: account))
		defer { BeamioNativeWallet.wipe(&keyBytes) }
		let backup = BeamioPGPBackup.decrypt(base64: body["encrypKeyArmored"] as? String ?? "", passwordString: BeamioChatRouteRegister.passwordString(privateKey: [UInt8](keyBytes)))
		XCTAssertEqual(try backup.get(), record.privateKeyArmor)
		// the signature is the account key's EIP-191 signature of the eight lines
		let message = BeamioChatRouteRegister.registrationMessage(
			wallet: account, keyID: body["keyID"] as? String ?? "", publicKeyBase64: body["publicKeyArmored"] as? String ?? "", encrypKeyBase64: body["encrypKeyArmored"] as? String ?? "",
			routeKeyID: body["routeKeyID"] as? String ?? "", timestamp: Int64(body["timestamp"] as? Int ?? 0), nonce: body["nonce"] as? String ?? ""
		)
		XCTAssertEqual(body["signature"] as? String, BeamioNativeEthSigner.signEip191(privateKey: [UInt8](keyBytes), message: message))
		// identityPublic now has its three parts
		let publicRecord = try XCTUnwrap(BeamioChatPgpKeychain.publicRecord(eoa: account))
		XCTAssertFalse(publicRecord.routePublicKeyArmor.isEmpty)
	}

	/// Run again after the identity exists: it is the active identity, nothing is generated and nothing is sent.
	func testASecondRunSendsNothing() throws {
		try XCTSkipUnless(BeamioPGPNative.linked, "X-19 framework not linked in this build")
		XCTAssertEqual(BeamioFirstIdentityCoordinator.run(eoa: account), .active)
		XCTAssertEqual(BeamioFirstIdentityCoordinator.run(eoa: account), .active)
		XCTAssertEqual(posted.count, 1)
	}
}
#endif
